    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.075, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 170+Math.sin(t*0.65)*55, 0.095, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.75+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4, 0.85],
    [380+Math.sin(t*0.38+4)*95, 50+Math.cos(t*0.85+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 100+Math.cos(t*0.7+1)*80, 0.1, 1.6, 0.8],
