  const n = 8; const act=aS/n, inh=iS/n, cross=cS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*1.0))/2;
  const bg2 = (Math.sin((sx+sy)*0.1+t*2.2)+Math.sin((sx-sy)*0.09-t*1.8))*0.25;
  const bg3 = Math.sin(sx*0.06+Math.sin(sy*0.04+t*0.5)*2+t)*0.15;
